sys_variable_value.value:
(function execute(inputs, outputs) {

  var gr = new GlideRecord('x_asscs_allos_o2c_task'); 

if (gr.get(inputs.id)) { 
    var currentValue = gr.u_luc_info_integracao || ""; // Garante que o campo não seja undefined ou null
    var newValue = inputs.lucKey ? inputs.lucKey.trim() : "";

    // Separar os valores existentes em um array, removendo espaços extras
    var valuesArray = currentValue.split(" | ").map(item => item.trim().toLowerCase());

    // Verifica se o novo valor já existe no array (sem case sensitive)
    if (!valuesArray.includes(newValue.toLowerCase())) {
        // Concatena corretamente
        var updatedValue = currentValue ? currentValue + " | " + newValue : newValue;

        // Adiciona logs antes da atualização
        gs.info("Atualizando registro ID: " + inputs.id);
        gs.info("Valor atual no campo: " + currentValue);
        gs.info("Novo valor a ser adicionado: " + newValue);
        gs.info("Novo valor final do campo: " + updatedValue);

        // Atualiza o registro
        gr.u_luc_info_integracao = updatedValue;
        gr.update();
        
        gs.info("Campo atualizado com sucesso.");
    } else {
        gs.info("Valor já existente, não atualizado.");
    }
} else {
    gs.warn("Registro não encontrado para ID: " + inputs.id);
}



})(inputs, outputs);

